using System;
using System.IO;
using System.Linq;
using MET.Core;
class RogueContentProgram {
 static Catalog c;static V checks=V.Arr(),details=V.Arr();
 static void Check(bool ok,string label){checks.Add(V.Map("name",label,"pass",ok));Console.WriteLine((ok?"PASS ":"FAIL ")+label);if(!ok)throw new Exception(label);}
 static void Cmd(string error,string label)=>Check(error=="",label+ (error==""?"":" : "+error));
 static bool Near(double a,double b)=>Math.Abs(a-b)<1e-6;
 static Game Fresh(){var g=new Game(c);g.new_game(20261014,0);g.select_block(0);g.choose_origin(g.s["origin_choices"][0].Text);g.s["block"]["reward_choices"]=V.Arr();return g;}
 static string Place(Game g,string kind,string tile,string op="commons",int count=3){var p=g.create_building(kind,tile,op,true);p["slots"]=V.Map();p["slot_types"]=V.Map();for(int i=0;i<count;i++){p["slots"]["p"+i]="";p["slot_types"]["p"+i]="Production";p["slots"]["o"+i]="";p["slot_types"]["o"+i]="Operations";}g.refresh_metrics();return p["id"].Text;}
 static void Cards(){foreach(string bid in new[]{"P09","R19","O08","B10"}){
  var g=Fresh();g.s["groups"]=V.Map();g.s["projects"]=V.Map("municipal",g.s["projects"]["municipal"],"homeless",g.s["projects"]["homeless"]);foreach(var cell in g.s["cells"].Values)cell["building"]="";
  string home=Place(g,"residence","0,0"),host=Place(g,bid=="O08"?"medical_clinic":"manufacturing","1,0"),neighbor=Place(g,"manufacturing","2,0"),remote=Place(g,"manufacturing","-2,1");
  Population.create(g,home,20);g.refresh_metrics();var baselineState=g.snapshot();var baseline=g.compiled["stats"].Duplicate(true);string type=bid=="B10"?"block":"building",target=bid=="B10"?g.s["block"]["id"].Text:host,slot=bid=="P09"?"p":"o";
  Cmd(Bonus.grant(g,bid,"fixture:copy:0"),"fixture grant "+bid);Cmd(Bonus.install(g,bid,type,target,type=="block"?"":slot+0),"fixture real install "+bid);
  var installed=g.compiled["stats"].Duplicate(true);
  if(bid=="P09"||bid=="R19"){var unmodified=new Game(c){s=baselineState.Duplicate(true)};var modified=new Game(c){s=g.snapshot()};foreach(var game in new[]{unmodified,modified}){game.s["projects"]["municipal"]["base_stats"]["output.energy"]=1.0;game.refresh_metrics();Cmd(Sim.tick(game,.1),"fixture actual constrained electricity simulation "+bid);}Check(unmodified.s["metrics"]["energy_ratio"].Double>modified.s["metrics"]["energy_ratio"].Double,"fixture extra electricity lowers actual limited supply ratio "+bid);details.Add(V.Map("scope","fixture_actual_simulation","bonus",bid,"before_metrics",unmodified.s["metrics"],"after_metrics",modified.s["metrics"],"before_audit",unmodified.s["audit"],"after_audit",modified.s["audit"]));}

  if(bid=="P09"){Check(installed[neighbor]["output.goods"].Double>baseline[neighbor]["output.goods"].Double&&Near(installed[remote]["output.goods"].Double,baseline[remote]["output.goods"].Double),"fixture P09 adjacent same operator improves remote stays baseline");Check(installed[host]["energy_demand"].Double>baseline[host]["energy_demand"].Double,"fixture P09 electric cost survives dispersed layout");g.s["projects"][neighbor]["operator_org"]="civic";g.refresh_metrics();Check(Near(g.compiled["stats"][neighbor]["output.goods"].Double,baseline[neighbor]["output.goods"].Double),"fixture P09 neighbor different operator no gain");}
  if(bid=="R19")Check(installed[home]["exposure_multiplier"].Double<baseline[home]["exposure_multiplier"].Double&&installed[host]["energy_demand"].Double>baseline[host]["energy_demand"].Double&&installed[host]["maintenance"].Double>baseline[host]["maintenance"].Double,"fixture R19 protection electricity maintenance tradeoff");
  if(bid=="O08")Check(installed[home]["shortage_multiplier"].Double<baseline[home]["shortage_multiplier"].Double&&installed[host]["service.medical"].Double<baseline[host]["service.medical"].Double,"fixture O08 shortage protection trades real medical capacity");
  if(bid=="B10")Check(installed[home]["housing"].Double<baseline[home]["housing"].Double&&installed[home]["service.education"].Double>baseline[home]["service.education"].Double&&installed[home]["population_maintenance"].Double>baseline[home]["population_maintenance"].Double,"fixture B10 education housing resident maintenance tradeoff");
  Cmd(Bonus.grant(g,bid,"fixture:copy:1"),"fixture second copy "+bid);Cmd(Bonus.install(g,bid,type,target,type=="block"?"":slot+1),"fixture append same object "+bid);Check(Near(Rules.copy_strength(g,2,bid),4.0/3),"fixture 1/3 additional strength "+bid);
  for(int level=1;level<=2;level++){var reward=Bonus.draw(g,"fixture:research:"+bid+":"+level,V.Arr(),V.Map("kind","research","bonus_ids",V.Arr(bid)));Check(reward["kind"].Text=="research","fixture research offers owned "+bid+" "+level);Cmd(Bonus.choose(g,reward["reward_id"].Text,bid),"fixture claim research "+bid+" "+level);Check(Bonus.blueprint_level(g,bid)==level&&g.s["block"]["bonus_wallet"][bid]["charges"].Long==0,"fixture blueprint upgrade no extra copies "+bid+" "+level);}
  details.Add(V.Map("scope","fixture","bonus",bid,"baseline",baseline,"installed",installed,"after_upgrade",g.compiled["stats"].Duplicate(true)));
 }}
 static void Events(){foreach(var definition in c.commission_events.Where(x=>x.Has("choices")))foreach(var branch in definition["choices"]){var g=Fresh();Cmd(Themes.select(g,definition["theme"].Text),"fixture choose theme "+definition["id"].Text);g.s["currency"]=500;foreach(string r in new[]{"food","material","goods"})g.s["projects"]["municipal"]["inventory"][r]=100;
  foreach(var bid in branch["bonus_ids"])Bonus.grant(g,bid.Text,"fixture:owned:"+bid.Text);
  string expectedKind=branch["reward_kind"].Text=="research"&&Bonus.research_candidates(g,branch["bonus_ids"]).Count==0?"copy":branch["reward_kind"].Text;var evt=V.Map("id",definition["id"],"status","offered","theme",definition["theme"],"revealed_seconds",0);g.s["block"]["theme"]["events"].Add(evt);g.s["block"]["theme"]["event_ids"].Add(definition["id"]);
  var before=V.Map();foreach(var r in branch.Get("resources",V.Map()).Keys)before[r]=g.inventory_total(r);
  string label=definition["id"].Text+"/"+branch["id"].Text;Cmd(Themes.choose_event(g,definition["id"].Text,branch["id"].Text),"fixture branch command "+label);Check(Near(g.s["currency"].Double,500-branch.Get("currency",0).Double),"fixture exact money "+label);foreach(var r in before.Keys)Check(Near(before[r].Double-g.inventory_total(r),branch["resources"][r].Double),"fixture exact real resource "+label+" "+r);
  Check(evt["status"].Text=="completed","fixture immediate branch complete "+label);var reward=Bonus.pending(g)[0];Check(reward["source"].Text=="theme_event:"+definition["id"].Text&&reward["kind"].Text==expectedKind,"fixture branch reward source and kind "+label);Check(reward["choices"].All(x=>branch["bonus_ids"].Contains(x["bonus_id"])),"fixture branch own candidate pool "+label);Cmd(Bonus.choose(g,reward["reward_id"].Text,reward["choices"][0]["bonus_id"].Text),"fixture claim normal reward "+label);var saved=g.snapshot().ToJson();Check(Themes.choose_event(g,definition["id"].Text,branch["id"].Text)!=""&&g.snapshot().ToJson()==saved,"fixture branch retry no repayment or reward "+label);var loaded=new Game(c){s=V.Parse(saved)};Check(Themes.choose_event(loaded,definition["id"].Text,branch["id"].Text)!=""&&loaded.snapshot().ToJson()==saved,"fixture saved branch re-read cannot reaward "+label);details.Add(V.Map("scope","fixture","branch",label,"event",evt,"reward",reward));
 }}
 static void UnownedResearch(){foreach(var definition in c.commission_events.Where(x=>x.Has("choices")))foreach(var branch in definition["choices"].Where(x=>x["reward_kind"].Text=="research")){var g=Fresh();Themes.select(g,definition["theme"].Text);g.s["block"]["bonus_wallet"]=V.Map();g.s["bonus_instances"]=V.Map();g.s["currency"]=500;foreach(string r in new[]{"food","material","goods"})g.s["projects"]["municipal"]["inventory"][r]=100;g.s["block"]["theme"]["events"].Add(V.Map("id",definition["id"],"theme",definition["theme"],"status","offered"));string saved=g.snapshot().ToJson();Check(Themes.choose_event(g,definition["id"].Text,branch["id"].Text)!=""&&g.snapshot().ToJson()==saved,"fixture unowned research rejects without pay or fallback "+definition["id"].Text+"/"+branch["id"].Text);}}
 static void QueuedResearch(){var g=Fresh();Themes.select(g,"industrial");g.s["currency"]=500;g.s["projects"]["municipal"]["inventory"]["material"]=100;Bonus.grant(g,"P09","fixture:owned-queued");var queued=Bonus.draw(g,"fixture:queued-existing",V.Arr(),V.Map("kind","research","bonus_ids",V.Arr("P09")));g.s["block"]["theme"]["events"].Add(V.Map("id","industrial_tech_review","status","offered","theme","industrial"));string saved=g.snapshot().ToJson();Check(Themes.choose_event(g,"industrial_tech_review","recover")!=""&&g.snapshot().ToJson()==saved,"fixture queued earlier research prevents paid duplicate upgrade without spend");Cmd(Bonus.choose(g,queued["reward_id"].Text,"P09"),"fixture claim prior research through normal command");Cmd(Themes.choose_event(g,"industrial_tech_review","recover"),"fixture paid research becomes available after prior claim");Check(Near(g.s["currency"].Double,435)&&Bonus.pending(g)[0]["kind"].Text=="research","fixture queued resolve then one paid legitimate research");}
 static Game ProofScene(){var g=Fresh();g.world_managed=true;g.s["currency"]=500;foreach(string r in new[]{"food","material","goods"})g.s["projects"]["municipal"]["inventory"][r]=100;Place(g,"hospital","1,1");Place(g,"secondary_school","0,2");g.refresh_metrics();return g;}
 static V Candidate(Game g,string profile)=>RogueContent.CaptureEnding(g,"civic")["candidates"].FirstOrDefault(x=>x["profile_id"].Text==profile)??V.Map();
 static void OperationProof(){
  var g=ProofScene();string remote=Place(g,"manufacturing","-4,0");Bonus.grant(g,"R19","fixture:remote-r19");Cmd(Bonus.install(g,"R19","building",remote,"o0"),"fixture far R19 install");string remoteClinic=Place(g,"medical_clinic","4,0");Bonus.grant(g,"O08","fixture:remote-o08");Cmd(Bonus.install(g,"O08","building",remoteClinic,"o0"),"fixture far O08 install");Cmd(Sim.tick(g,.1),"fixture far cards actually operate");Check(Candidate(g,"care_neighborhood").Count==0,"fixture remote R19 O08 cannot borrow unrelated hospital coverage");
  g=ProofScene();string home=g.playable_ids().First(id=>g.s["projects"][id]["def"].Text=="homestead").Text;g.s["projects"][home]["slots"]["proof"]="";g.s["projects"][home]["slot_types"]["proof"]="Operations";Bonus.grant(g,"O03","fixture:negative");Cmd(Bonus.install(g,"O03","building",home,"proof"),"fixture negative shortage O03 install");Cmd(Sim.tick(g,.1),"fixture O03 actually operate");Check(Candidate(g,"care_neighborhood").Count==0,"fixture O03 worsening shortage is not beneficial care evidence");
  g=ProofScene();string clinic=Place(g,"medical_clinic","1,0");Cmd(Sim.tick(g,.1),"fixture prior slice before newly deployed O08");Bonus.grant(g,"O08","fixture:fresh");Cmd(Bonus.install(g,"O08","building",clinic,"o0"),"fixture newly deployed O08");Check(Candidate(g,"care_neighborhood").Count==0,"fixture newly deployed unoperated card cannot qualify");Cmd(Sim.tick(g,.1),"fixture level zero O08 actual operation");Check(Candidate(g,"care_neighborhood")["grade"].Long==0,"fixture actual operated level zero qualifies");g.s["block"]["blueprint_levels"]["O08"]=2;g.refresh_metrics();Check(Candidate(g,"care_neighborhood")["grade"].Long==0,"fixture newly upgraded unoperated blueprint cannot raise grade");Cmd(Sim.tick(g,.1),"fixture upgraded O08 actual operation");Check(Candidate(g,"care_neighborhood")["grade"].Long==2,"fixture next actual operation can raise grade");
  g=ProofScene();string careHost=Place(g,"medical_clinic","1,0");g.s["projects"][careHost]["slots"]["l0"]="";g.s["projects"][careHost]["slot_types"]["l0"]="Logistics";Bonus.grant(g,"R05","fixture:beneficial-decay");Cmd(Bonus.install(g,"R05","building",careHost,"l0"),"fixture R05 real card install");Cmd(Sim.tick(g,.1),"fixture R05 real medical operation");Check(Candidate(g,"care_neighborhood").Count>0,"fixture R05 beneficial priority and decay have real medical receipts despite capacity penalty");details.Add(V.Map("scope","fixture_R05_actual_operation","evidence",RogueContent.CaptureEnding(g,"civic"),"service_links",g.s["metrics"]["service_links"]));
  g=ProofScene();Bonus.grant(g,"B10","fixture:pooled");Cmd(Bonus.install(g,"B10","block",g.s["block"]["id"].Text),"fixture pooled B10 install");Cmd(Sim.tick(g,.1),"fixture pooled B10 actual service");var result=RogueContent.CaptureEnding(g,"civic");Check(result["candidates"].Any(x=>x["profile_id"].Text=="learning_neighborhood"),"fixture small actual B10 pool member qualifies with contributed education receipts");details.Add(V.Map("scope","fixture_actual_pool","evidence",result,"service_pools",g.s["metrics"]["service_pools"],"service_links",g.s["metrics"]["service_links"]));
 }
 static void Profiles(){foreach(var profile in RogueContent.Profiles(c)){var city=new CitySession(c);city.New(20261014,0,"成果夹具");Cmd(city.BeginDistrict(0,"industrial"),"fixture initial district");var g=city.FocusedGame;var before=g.snapshot();Cmd(g.choose_origin(g.s["origin_choices"][0].Text),"fixture origin");city.AfterLocalCommand(before);string source=city.FocusedBlockId;
  // Explicit fixture: supplied buildings/resources and completed theme. Actual Sim.tick must supply operating and receipt proof; not a natural route.
  Themes.select(g,profile["theme"].Text);g.s["block"]["theme"]["completed"]=true;string bid=profile["id"].Text=="heat_neighborhood"?"P05":profile["id"].Text=="circular_industry"?"P06":profile["id"].Text=="care_neighborhood"?"O08":"B10";string tile=g.s["cells"].Keys.Where(t=>g.s["cells"][t]["building"].Text==""&&!g.s["cells"][t]["traits"].Contains("tile.water")).OrderBy(t=>Hex.distance("0,1",t)).First();string host=Place(g,bid=="O08"?"medical_clinic":"manufacturing",tile);Bonus.grant(g,bid,"fixture:legacy");Cmd(Bonus.install(g,bid,bid=="B10"?"block":"building",bid=="B10"?g.s["block"]["id"].Text:host,bid=="B10"?"":bid=="O08"?"o0":"p0"),"fixture source deployed "+bid);g.s["block"]["blueprint_levels"][bid]=2;g.s["currency"]=500;foreach(string r in new[]{"food","material","goods"})g.s["projects"]["municipal"]["inventory"][r]=100;
  if(bid=="P05"){Bonus.grant(g,"B02","fixture:real-heat-receiver");Cmd(Bonus.install(g,"B02","block",g.s["block"]["id"].Text),"fixture install real heat use");}
  if(bid=="B10"){string schoolTile=g.s["cells"].Keys.Where(t=>g.s["cells"][t]["building"].Text==""&&!g.s["cells"][t]["traits"].Contains("tile.water")).OrderBy(t=>Hex.distance("0,1",t)).First();Place(g,"secondary_school",schoolTile);}
  g.refresh_metrics();Cmd(Sim.tick(g,.1),"fixture actual source operation "+profile["id"].Text);
  g.s["dt"]=0.0;Block.on_dt_zero(g);Check(g.s["block"]["ending"]["build_result"]["candidates"].Any(x=>x["profile_id"]==profile["id"]&&x["grade"].Long==2),"fixture DT0 locks real simulated operation evidence "+profile["id"].Text);var lockJson=g.s["block"]["ending"]["build_result"].ToJson();Cmd(Block.claim_capstone(g),"fixture original landmark "+profile["id"].Text);Cmd(city.ChooseBuildLegacy(profile["id"].Text),"fixture choose one build result "+profile["id"].Text);Check(city.ChooseBuildLegacy(profile["id"].Text)!="","fixture single source one choice "+profile["id"].Text);Block.on_dt_zero(g);Check(g.s["block"]["ending"]["build_result"].ToJson()==lockJson,"fixture zero callback evidence frozen "+profile["id"].Text);
  string specialization=profile["specializations"][0].Text,opportunity="build:"+source;g.s["currency"]=500;foreach(string r in new[]{"food","material","goods"})g.s["projects"]["municipal"]["inventory"][r]=100;var quote=city.StartupView(false,specialization,source,opportunity)["quote"];double cash=g.s["currency"].Double;var stocks=V.Map();foreach(var r in quote["stock"].Keys)stocks[r]=g.inventory_total(r);Cmd(city.BeginBlock(1,specialization,source,opportunity),"fixture paid successor "+profile["id"].Text);Check(Near(cash-g.s["currency"].Double,quote["money"].Double),"fixture real startup debit "+profile["id"].Text);foreach(var r in stocks.Keys)Check(Near(stocks[r].Double-g.inventory_total(r),quote["stock"][r].Double),"fixture real startup stock "+profile["id"].Text+" "+r);var target=city.FocusedGame;before=target.snapshot();Cmd(target.choose_origin(target.s["origin_choices"][0].Text),"fixture successor origin");city.AfterLocalCommand(before);var entry=city.Block(city.FocusedBlockId)["start_sources"];Check(entry["opportunity"]["profile_id"]==profile["id"]&&entry["opportunity"]["rules"].Count>0&&entry["settled"].Bool,"fixture source grade rules and cost retained "+profile["id"].Text);Check(g.s["block"]["capstone"].Count>0&&!target.s["block"].Has("capstone"),"fixture landmark stays original block "+profile["id"].Text);if(profile["id"].Text=="learning_neighborhood"){
   string occupied=target.playable_ids().First(id=>target.s["projects"][id]["def"].Text=="homestead").Text;target.s["projects"][occupied]["slots"]["proof"]="";target.s["projects"][occupied]["slot_types"]["proof"]="Operations";
   string serviceTile=target.s["cells"].Keys.Where(t=>target.s["cells"][t]["building"].Text==""&&!target.s["cells"][t]["traits"].Contains("tile.water")).OrderBy(t=>Hex.distance(target.s["projects"][occupied]["tile"].Text,t)).First();string service=Place(target,"neighborhood",serviceTile);
   foreach(string bonus in new[]{"B10","P02","O05"}){Bonus.grant(target,bonus,"fixture:paid-learning:"+bonus);Cmd(Bonus.install(target,bonus,bonus=="B10"?"block":"building",bonus=="B10"?target.s["block"]["id"].Text:bonus=="P02"?service:occupied,bonus=="B10"?"":bonus=="P02"?"p0":"proof"),"fixture paid learning install "+bonus);}
   foreach(var group in target.s["groups"].Values)group["education"]=80.0;target.refresh_metrics();var plain=new Game(c){s=target.snapshot(),world_managed=true,world_effects=V.Map("sources",V.Map())};var charter=new Game(c){s=target.snapshot(),world_managed=true,world_effects=target.world_effects.Duplicate(true)};plain.refresh_metrics();charter.refresh_metrics();Cmd(Sim.tick(plain,.1),"fixture ordinary education capacity real operation");Cmd(Sim.tick(charter,.1),"fixture paid learning capacity real operation");double normalCapacity=plain.s["metrics"]["service_pools"].Values.Where(pool=>pool["kind"].Text=="education").Sum(pool=>pool["capacity"].Double),paidCapacity=charter.s["metrics"]["service_pools"].Values.Where(pool=>pool["kind"].Text=="education").Sum(pool=>pool["capacity"].Double);Check(paidCapacity>normalCapacity,"fixture paid B10 P02 O05 combined actual final education capacity improves");Check(charter.compiled["stats"][occupied]["housing"].Double<plain.compiled["stats"][occupied]["housing"].Double,"fixture paid learning real housing cost retained");details.Add(V.Map("scope","fixture_paid_learning_actual_simulation","ordinary_capacity",normalCapacity,"paid_capacity",paidCapacity,"plain_pools",plain.s["metrics"]["service_pools"],"charter_pools",charter.s["metrics"]["service_pools"]));
  }
  string delivered=target.snapshot().ToJson();city.AfterLocalCommand(before);Check(target.snapshot().ToJson()==delivered,"fixture startup applied once "+profile["id"].Text);var saved=city.snapshot();var restored=new CitySession(c);Cmd(restored.Restore(V.Parse(saved.ToJson())),"fixture legacy full city roundtrip "+profile["id"].Text);Check(restored.snapshot().ToJson()==saved.ToJson(),"fixture source effects records preserved no reissue "+profile["id"].Text);details.Add(V.Map("scope","fixture","profile",profile["id"],"opportunity",entry["opportunity"],"quote",quote,"source_evidence",g.s["block"]["ending"]["build_result"]));
  city.FocusBlock(source);g.s["block"]["ending"].Remove("build_result");city.s["legacy"]["build_results"]=V.Map();Check(city.ChooseBuildLegacy(profile["id"].Text)!=""&&city.BuildLegacyView()["pending"].Count==0,"fixture old ending has no retrospective qualification "+profile["id"].Text);
 }}
 static int Main(string[] args){try{c=new Catalog(args[0]);if(args.Length>2&&(args[2]=="normal"||args[2]=="civic")){var journey=args[2]=="civic"?RogueContentWalkthrough.ExecuteCivic(c,0,Console.WriteLine):RogueContentWalkthrough.Execute(c,0,Console.WriteLine);File.WriteAllText(args[1],journey.ToJson(true));File.WriteAllText(args[1]+".city.json",journey["city"].ToJson(true));return 0;}Cards();Profiles();Events();OperationProof();UnownedResearch();QueuedResearch();var report=V.Map("ok",true,"scope","Explicit fixtures for configuration and command coverage; injected eligibility is not a normal play journey.","checks",checks,"details",details);File.WriteAllText(args[1],report.ToJson(true));Console.WriteLine("ROGUE FIXTURE PASS "+checks.Count);return 0;}catch(Exception e){Console.Error.WriteLine(e);if(RogueContentWalkthrough.LastAttempt!=null)File.WriteAllText(args[1]+".attempt.city.json",RogueContentWalkthrough.LastAttempt.ToJson(true));File.WriteAllText(args[1],V.Map("ok",false,"checks",checks,"details",details,"error",e.ToString()).ToJson(true));return 1;}}
}
